import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const _=JSON.parse('{"title":"连接 MySQL","description":"填写 MySQL 地址、库名与专用账号，核对 TLS 和字符集，测试并保存连接后进入查询工作台。","frontmatter":{"title":"连接 MySQL","description":"填写 MySQL 地址、库名与专用账号，核对 TLS 和字符集，测试并保存连接后进入查询工作台。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/mysql.md","filePath":"zh/使用指南/连接MySQL.md"}'),o={name:"zh/guide/mysql.md"};function s(n,t,i,h,l,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="连接-mysql" tabindex="-1">连接 MySQL <a class="header-anchor" href="#连接-mysql" aria-label="Permalink to &quot;连接 MySQL&quot;">​</a></h1><p>本页配置外部 MySQL，不是平台的内置关系库。先向数据库负责人取得地址、库名、专用账号、端口及证书要求，并确认平台开发环境可访问该服务。</p><h2 id="_1-填写连接" tabindex="-1">1. 填写连接 <a class="header-anchor" href="#_1-填写连接" aria-label="Permalink to &quot;1. 填写连接&quot;">​</a></h2><p>进入 <strong>“数据中心” → “接入源” → “新建连接”</strong>，选择 <strong>“MySQL”</strong>。</p><table tabindex="0"><thead><tr><th>字段</th><th>怎样填写</th></tr></thead><tbody><tr><td>连接名称</td><td>便于识别用途的名称，不填密码等敏感资料</td></tr><tr><td>主机地址</td><td>平台能够访问的数据库主机，不是自己电脑的 localhost</td></tr><tr><td>端口</td><td>默认 3306；数据库另有安排时使用实际端口</td></tr><tr><td>数据库名</td><td>已存在且获准访问的业务库</td></tr><tr><td>用户名、密码</td><td>数据库负责人提供的专用账号，不因表单提示 root 就共用最高权限账号</td></tr><tr><td>SSL/TLS 配置</td><td>按服务要求选择并准备证书，不通过禁用校验处理证书错误</td></tr><tr><td>字符集、查询超时</td><td>在其他参数中按实际库和业务约定调整；默认字符集为 utf8mb4</td></tr></tbody></table><p>连接库名不会替你新建数据库，也不会自动获得所有表的权限。</p><h2 id="_2-测试并保存" tabindex="-1">2. 测试并保存 <a class="header-anchor" href="#_2-测试并保存" aria-label="Permalink to &quot;2. 测试并保存&quot;">​</a></h2><p>点击 <strong>“测试连接”</strong>，查看结果。成功后点击 <strong>“创建连接”</strong>，再回列表核对名称、类型与保存后的测试状态。</p><p>失败时先核对网络、账号权限、库名和证书。不要把真实密码粘贴到 AI 或普通工单。保存与测试的区别见<a href="/induframe-docs/zh/guide/access-sources.html">管理接入源</a>。</p><h2 id="_3-打开查询工作台" tabindex="-1">3. 打开查询工作台 <a class="header-anchor" href="#_3-打开查询工作台" aria-label="Permalink to &quot;3. 打开查询工作台&quot;">​</a></h2><p>打开已保存连接，先查看可用表和已有查询。需要新查询时使用 <strong>“新建查询”</strong>，核对 SQL 后执行；检查结果，再维护“输出配置”并保存。</p><p>连接成功不代表每条 SQL、全部表或写入操作都已获准。涉及业务写入时先取得授权，不用删除、更新语句试通连接。</p><p>下一步：<a href="/induframe-docs/zh/guide/datapoints.html">数据点列表</a> · <a href="/induframe-docs/zh/guide/builtin-stores.html">内置库</a>。修改连接时留意已保存密码的提示，通用维护与删除条件见<a href="/induframe-docs/zh/guide/access-sources.html">管理接入源</a>。</p>',13)])])}const u=a(o,[["render",s]]);export{_ as __pageData,u as default};
